1	import { db } from "../lib/db";
2	import {
3	  registrarConfigured,
4	  renewDomain,
5	  transfersAvailable,
6	  getTransfer,
7	  domainInfo,
8	  transferOutcome,
9	  transferStatusLabel,
10	} from "../lib/registrar";
11	import {
12	  TRANSFER_STALE_DAYS,
13	  TRANSFER_TERM_YEARS,
14	  settleCompletedTransferIn,
15	  settleFailedTransferIn,
16	} from "../lib/domain-transfer";
17	import { vpsTerm, vpsTermPriceCents, domainTerm, domainTermPriceCents, addMonths } from "../lib/billing-terms";
18	import { dedicatedIpMonthlyCents } from "../lib/dedicated-ip";
19	import { extraDiskPerGbCents } from "../lib/disk-expand";
20	import { extraDiskCentsAt, extraDiskLabel } from "../lib/extra-disk";
21	import { debitWallet, InsufficientBalanceError } from "../lib/wallet";
22	import { invoiceCreateData } from "../lib/invoices";
23	
24	/** Thrown when a compare-and-swap shows someone else already advanced the period. */
25	class AlreadyRenewedError extends Error {}
26	
27	const GRACE_DAYS = Number(process.env.NXEON_GRACE_DAYS ?? 3);
28	const RENEW_DAYS = 30;
29	const DOMAIN_RENEW_WINDOW_DAYS = 7;
30	/** Days a server stays SUSPENDED (unpaid) before it is permanently terminated. */
31	const TERMINATE_DAYS = Number(process.env.NXEON_TERMINATE_DAYS ?? 10);
32	/** Warn the customer this many days before termination. */
33	const WARN_BEFORE_TERMINATE_DAYS = Number(process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS ?? 2);
34	const DAY = 86400_000;
35	
36	/**
37	 * Subscription sweep, run periodically by the worker:
38	 *  - expired + autoRenew + sufficient balance  -> charge wallet, extend 30 days
39	 *  - expired beyond grace (or autoRenew off)   -> queue SUSPEND with unpaid note
40	 * Free servers (isFree) are never touched.
41	 */
42	export async function billingSweep() {
43	  const now = new Date();
44	  const ipMonthly = await dedicatedIpMonthlyCents(); // admin setting; 0 = included
45	  // Per-GB/month price for extra ROOT DISK. Read once per sweep; every server that
46	  // bought extra storage renews at plan + (extraDiskGB x this) x months, so the
47	  // upsell keeps billing every cycle rather than being a one-off charge.
48	  const extraDiskPerGb = await extraDiskPerGbCents();
49	  const extraDiskMonthlyFor = (s: { extraDiskGB: number }) =>
50	    extraDiskCentsAt(s.extraDiskGB, extraDiskPerGb);
51	
52	  // Renewal warnings: notify once when a paid server is within 3 days of expiry
53	  const soon = new Date(now.getTime() + 3 * 86400_000);
54	  const upcoming = await db.server.findMany({
55	    where: {
56	      isFree: false,
57	      expiresAt: { gt: now, lt: soon },
58	      status: { in: ["RUNNING", "STOPPED"] },
59	    },
60	    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
61	  });
62	  for (const server of upcoming) {
63	    const warnCents = server.gamePlan
64	      ? server.gamePlan.priceCents
65	      : vpsTermPriceCents(server.plan.priceCents, server.termMonths) +
66	        (server.dedicatedIp ? ipMonthly * server.termMonths : 0) +
67	        extraDiskMonthlyFor(server) * server.termMonths;
68	    if (server.autoRenew && server.user.balanceCents >= warnCents) continue;
69	    const already = await db.notification.findFirst({
70	      where: {
71	        userId: server.userId,
72	        title: { contains: server.hostname },
73	        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
74	        AND: { title: { contains: "renews soon" } },
75	      },
76	    });
77	    if (!already) {
78	      await db.notification.create({
79	        data: {
80	          userId: server.userId,
81	          title: `${server.hostname} renews soon — action needed`,
82	          body: server.autoRenew
83	            ? `Renewal is $${(warnCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
84	            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
85	          href: `/dashboard/servers/${server.id}`,
86	        },
87	      });
88	    }
89	  }
90	  const due = await db.server.findMany({
91	    where: {
92	      isFree: false,
93	      expiresAt: { lt: now },
94	      status: { in: ["RUNNING", "STOPPED"] },
95	    },
96	    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
97	  });
98	
99	  for (const server of due) {
100	    const graceEnd = new Date(server.expiresAt!.getTime() + GRACE_DAYS * 86400_000);
101	    const renewTerm = vpsTerm(server.termMonths);
102	    const isGame = !!server.gamePlan;
103	    const renewMonths = isGame ? server.gamePlan!.termMonths : renewTerm.months;
104	    // Extra root disk is billed EVERY cycle at the current per-GB price, on top of
105	    // the plan. `extraDiskGB` is only ever set by the worker AFTER the disk really
106	    // grew, so a customer can never renew on storage that was never delivered.
107	    const extraDiskMonthly = isGame ? 0 : extraDiskMonthlyFor(server);
108	    const extraDiskCents = extraDiskMonthly * renewMonths;
109	    const renewCents = isGame
110	      ? server.gamePlan!.priceCents
111	      : vpsTermPriceCents(server.plan.priceCents, renewTerm.months) +
112	        // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP
113	        // (the DedicatedIp row is the source of truth), not off the intent flag —
114	        // otherwise a NAT-fallback server is charged forever for an IP it never got.
115	        (server.dedicatedIp ? ipMonthly * renewTerm.months : 0) +
116	        extraDiskCents;
117	
118	    // NOTE: `server.user.balanceCents` came from a snapshot taken before this loop,
119	    // so it is stale as soon as the first renewal in this pass debits the wallet.
120	    // Never gate the charge on it — `debitWallet` re-checks funds atomically, and a
121	    // compare-and-swap on `expiresAt` stops a concurrent renewNow()/second pass from
122	    // charging the same period twice.
123	    let renewed = false;
124	    if (server.autoRenew) {
125	      const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
126	      const newExpiry = addMonths(base, renewMonths);
127	      try {
128	        await db.$transaction(async (tx) => {
129	          const advanced = await tx.server.updateMany({
130	            where: { id: server.id, expiresAt: server.expiresAt },
131	            data: { expiresAt: newExpiry },
132	          });
133	          if (advanced.count === 0) throw new AlreadyRenewedError();
134	          await debitWallet(tx, server.userId, renewCents);
135	          await tx.walletTransaction.create({
136	            data: {
137	              userId: server.userId,
138	              amountCents: -renewCents,
139	              description: `Renewal: ${isGame ? server.gamePlan!.name : `${server.plan.name} VPS`} (${server.hostname})`,
140	            },
141	          });
142	          // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
143	          // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
144	          // never producing a second invoice for the same period.
145	          const renewLabel = isGame ? server.gamePlan!.name : `${server.plan.name} VPS`;
146	          await tx.invoice.create({
147	            data: invoiceCreateData({
148	              userId: server.userId,
149	              description: `Renewal: ${renewLabel} (${server.hostname})`,
150	              status: "PAID",
151	              period: { start: server.expiresAt, end: newExpiry },
152	              // Extra disk gets its OWN line so the customer sees exactly what the
153	              // permanent storage costs each cycle; the lines sum back to renewCents.
154	              lineItems: [
155	                {
156	                  description: `${renewLabel} — ${server.hostname}`,
157	                  qty: 1,
158	                  unitCents: renewCents - extraDiskCents,
159	                  amountCents: renewCents - extraDiskCents,
160	                },
161	                ...(extraDiskCents > 0
162	                  ? [
163	                      {
164	                        description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthly / 100).toFixed(2)}/mo)`,
165	                        qty: 1,
166	                        unitCents: extraDiskCents,
167	                        amountCents: extraDiskCents,
168	                      },
169	                    ]
170	                  : []),
171	              ],
172	            }),
173	          });
174	          await tx.auditLog.create({
175	            data: { userId: server.userId, action: "billing.renewed", detail: server.id },
176	          });
177	        });
178	        renewed = true;
179	        console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
180	      } catch (e) {
181	        if (e instanceof InsufficientBalanceError) {
182	          console.log(`[billing] insufficient balance for ${server.hostname} — falling through to grace/suspend`);
183	        } else if (e instanceof AlreadyRenewedError) {
184	          renewed = true; // someone else advanced the period; nothing owed here
185	        } else {
186	          throw e;
187	        }
188	      }
189	    }
190	    if (renewed) {
191	      // nothing further this pass
192	    } else if (now > graceEnd) {
193	      const pending = await db.job.count({
194	        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
195	      });
196	      if (pending === 0) {
197	        await db.server.update({
198	          where: { id: server.id },
199	          data: { suspendedNote: "unpaid — renew from your billing page to restore access" },
200	        });
201	        await db.job.create({ data: { type: "SUSPEND", serverId: server.id } });
202	        await db.auditLog.create({
203	          data: { userId: server.userId, action: "billing.suspended_unpaid", detail: server.id },
204	        });
205	        await db.notification.create({
206	          data: {
207	            userId: server.userId,
208	            title: `${server.hostname} suspended — payment overdue`,
209	            body: "Pay from the server page to restore access instantly.",
210	            href: `/dashboard/servers/${server.id}`,
211	          },
212	        });
213	        console.log(`[billing] suspending unpaid ${server.hostname}`);
214	      }
215	    }
216	  }
217	
218	  await terminateOverdue(now);
219	
220	  await domainAutoRenewSweep(now);
221	
222	  // Poll in-flight inbound transfers on the same cadence as domain renewals —
223	  // domain upkeep all lives on one timer.
224	  try {
225	    await domainTransferInSweep(now);
226	  } catch (e) {
227	    console.error("[billing] domain transfer-in sweep error", e);
228	  }
229	}
230	
231	/* ------------------------------------------------------------------ *
232	 * Inbound domain transfers (transfer-in)
233	 * ------------------------------------------------------------------ */
234	
235	/** Remind the customer to approve the confirmation email at most this often. */
236	const TRANSFER_NUDGE_DAYS = 3;
237	
238	/**
239	 * Poll every TRANSFER_PENDING domain and move it to its real state.
240	 *
241	 * An ICANN transfer takes ~5-7 days and only completes once the owner approves
242	 * an email from the LOSING registrar, so this is a slow poll, not a spinner:
243	 *   completed -> ACTIVE, dates taken from the registrar, auth code scrubbed
244	 *   failed    -> TRANSFER_FAILED, wallet credited back, reason recorded
245	 *   pending   -> raw registrar status refreshed for display, gentle nudge
246	 *
247	 * Every mutation goes through the shared CAS-guarded settle helpers, so a
248	 * re-run, two workers racing, or a customer cancelling at the same moment can
249	 * never credit the same transfer twice.
250	 */
251	async function domainTransferInSweep(now: Date) {
252	  if (!transfersAvailable()) return; // registrar not configured — skip silently
253	
254	  const pending = await db.domain.findMany({
255	    where: { status: "TRANSFER_PENDING", isTransferIn: true },
256	  });
257	
258	  for (const domain of pending) {
259	    try {
260	      const info = await getTransfer(domain.name, domain.transferStartedAt);
261	
262	      // No transfer on record. Normal once a transfer settles and drops off the
263	      // registrar's list — resolve it against the account rather than guessing.
264	      if (!info) {
265	        const owned = await domainInfo(domain.name).catch(() => null);
266	        if (owned?.expires) {
267	          await completeTransferIn(domain, "completed", owned);
268	          continue;
269	        }
270	        const startedAt = domain.transferStartedAt ?? domain.createdAt;
271	        const ageDays = (now.getTime() - startedAt.getTime()) / DAY;
272	        if (ageDays > TRANSFER_STALE_DAYS) {
273	          await failTransferIn(
274	            domain,
275	            null,
276	            `The registrar has no record of this transfer after ${Math.round(ageDays)} days. It did not complete.`
277	          );
278	        }
279	        continue;
280	      }
281	
282	      const outcome = transferOutcome(info.status);
283	
284	      if (outcome === "completed") {
285	        const owned = await domainInfo(domain.name).catch(() => null);
286	        await completeTransferIn(domain, info.status, owned);
287	        continue;
288	      }
289	
290	      if (outcome === "failed") {
291	        await failTransferIn(domain, info.status, transferStatusLabel(info.status));
292	        continue;
293	      }
294	
295	      // Still in flight — keep the displayed registrar status fresh.
296	      if (info.status !== domain.transferStatus || (info.email && info.email !== domain.transferEmail)) {
297	        await db.domain.update({
298	          where: { id: domain.id },
299	          data: { transferStatus: info.status, ...(info.email ? { transferEmail: info.email } : {}) },
300	        });
301	      }
302	      await nudgeTransferApproval(domain, info.status, info.email, now);
303	    } catch (e) {
304	      // One unhappy domain must never abort the sweep. Nothing is settled and
305	      // no money moves on an unknown state — we simply try again next pass.
306	      console.error(`[billing] transfer-in poll failed for ${domain.name}`, e);
307	    }
308	  }
309	}
310	
311	async function completeTransferIn(
312	  domain: { id: string; name: string; userId: string },
313	  rawStatus: string,
314	  owned: { expires?: Date; created?: Date } | null
315	) {
316	  const expiresAt = owned?.expires ?? new Date(Date.now() + TRANSFER_TERM_YEARS * 365 * DAY);
317	  const settled = await settleCompletedTransferIn({
318	    domainId: domain.id,
319	    transferStatus: rawStatus,
320	    registeredAt: owned?.created ?? new Date(),
321	    expiresAt,
322	  });
323	  if (!settled) return;
324	
325	  await db.auditLog.create({
326	    data: { userId: domain.userId, action: "domain.transfer_in.completed", detail: domain.name },
327	  });
328	  await db.notification.create({
329	    data: {
330	      userId: domain.userId,
331	      title: `${domain.name} transferred in successfully`,
332	      body: `It's now managed here and expires ${expiresAt.toISOString().slice(0, 10)} — the transfer added a year. DNS and auto-renew are ready to set up.`,
333	      href: `/dashboard/domains/${domain.id}`,
334	    },
335	  });
336	  console.log(`[billing] transfer-in completed for ${domain.name}`);
337	}
338	
339	async function failTransferIn(
340	  domain: { id: string; name: string; userId: string; priceCents: number },
341	  rawStatus: string | null,
342	  reason: string
343	) {
344	  const settled = await settleFailedTransferIn({
345	    domainId: domain.id,
346	    transferStatus: rawStatus,
347	    reason,
348	  });
349	  if (!settled) return;
350	
351	  await db.notification.create({
352	    data: {
353	      userId: domain.userId,
354	      title: `${domain.name} transfer did not complete`,
355	      body: `${reason} We've credited $${(domain.priceCents / 100).toFixed(2)} back to your wallet. The most common cause is the confirmation email from your old registrar not being approved in time — you can start a new transfer whenever you're ready.`,
356	      href: `/dashboard/domains/${domain.id}`,
357	    },
358	  });
359	  console.log(`[billing] transfer-in failed for ${domain.name}: ${reason}`);
360	}
361	
362	/**
363	 * Nothing completes until the customer approves the losing registrar's email,
364	 * and that email is easy to miss. Nudge once every few days while we're waiting
365	 * — deduped on the notification log, same as the other billing reminders.
366	 */
367	async function nudgeTransferApproval(
368	  domain: { id: string; name: string; userId: string; transferStartedAt: Date | null; createdAt: Date },
369	  rawStatus: string,
370	  email: string | null,
371	  now: Date
372	) {
373	  const startedAt = domain.transferStartedAt ?? domain.createdAt;
374	  if (now.getTime() - startedAt.getTime() < 2 * DAY) return; // give them room first
375	
376	  const already = await db.notification.findFirst({
377	    where: {
378	      userId: domain.userId,
379	      title: { contains: domain.name },
380	      AND: { title: { contains: "still waiting" } },
381	      createdAt: { gt: new Date(now.getTime() - TRANSFER_NUDGE_DAYS * DAY) },
382	    },
383	  });
384	  if (already) return;
385	
386	  await db.notification.create({
387	    data: {
388	      userId: domain.userId,
389	      title: `${domain.name} transfer is still waiting`,
390	      body:
391	        `Registrar status: ${transferStatusLabel(rawStatus)}. ` +
392	        (email ? `Check ${email} ` : "Check the inbox for the domain's registered contact ") +
393	        `for the confirmation email from your CURRENT registrar and approve it. Transfers normally take 5–7 days and expire if the approval never arrives.`,
394	      href: `/dashboard/domains/${domain.id}`,
395	    },
396	  });
397	}
398	
399	/**
400	 * Terminate servers that have been SUSPENDED (unpaid) past the termination window,
401	 * reclaiming disk + dedicated IP. Warns the customer before the final deletion.
402	 * A payment before this point unsuspends the server, so this only ever hits
403	 * genuinely abandoned accounts. Free servers are never terminated.
404	 */
405	async function terminateOverdue(now: Date) {
406	  const suspended = await db.server.findMany({
407	    where: { isFree: false, status: "SUSPENDED", expiresAt: { not: null } },
408	  });
409	  for (const server of suspended) {
410	    const terminateAt = server.expiresAt!.getTime() + (GRACE_DAYS + TERMINATE_DAYS) * DAY;
411	    const warnAt = terminateAt - WARN_BEFORE_TERMINATE_DAYS * DAY;
412	
413	    if (now.getTime() >= terminateAt) {
414	      const pending = await db.job.count({
415	        where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
416	      });
417	      if (pending > 0) continue;
418	      await db.server.update({ where: { id: server.id }, data: { status: "DELETING" } });
419	      await db.job.create({ data: { type: "DELETE", serverId: server.id } });
420	      await db.auditLog.create({
421	        data: { userId: server.userId, action: "billing.terminated_unpaid", detail: server.id },
422	      });
423	      await db.notification.create({
424	        data: {
425	          userId: server.userId,
426	          title: `${server.hostname} was permanently deleted`,
427	          body: "Your server and its data were removed after prolonged non-payment.",
428	        },
429	      });
430	      console.log(`[billing] terminating abandoned ${server.hostname}`);
431	    } else if (now.getTime() >= warnAt) {
432	      const already = await db.notification.findFirst({
433	        where: {
434	          userId: server.userId,
435	          title: { contains: server.hostname },
436	          AND: { title: { contains: "will be deleted" } },
437	          createdAt: { gt: new Date(now.getTime() - 2 * DAY) },
438	        },
439	      });
440	      if (!already) {
441	        await db.notification.create({
442	          data: {
443	            userId: server.userId,
444	            title: `${server.hostname} will be deleted soon`,
445	            body: `This suspended server and all its data will be permanently deleted on ${new Date(terminateAt).toISOString().slice(0, 10)} unless you pay. Restore it now from your billing page.`,
446	            href: `/dashboard/servers/${server.id}`,
447	          },
448	        });
449	      }
450	    }
451	  }
452	}
453	
454	/**
455	 * Auto-renew domains expiring within 7 days when the owner opted in and has
456	 * the funds. Charges the wallet, extends expiry +365d and notifies the owner.
457	 * Failures (registrar error, misconfig) notify the owner to renew manually and
458	 * never charge the wallet.
459	 */
460	async function domainAutoRenewSweep(now: Date) {
461	  if (!registrarConfigured()) return; // registrar not configured — skip silently
462	
463	  const cutoff = new Date(now.getTime() + DOMAIN_RENEW_WINDOW_DAYS * 86400_000);
464	  const domains = await db.domain.findMany({
465	    where: {
466	      autoRenew: true,
467	      status: "ACTIVE",
468	      expiresAt: { not: null, lt: cutoff },
469	    },
470	    include: { user: true },
471	  });
472	
473	  for (const domain of domains) {
474	    if (!domain.expiresAt) continue;
475	    const dTerm = domainTerm(domain.termYears);
476	    const dRenewCents = domainTermPriceCents(domain.priceCents, dTerm.years); // retail (customer)
477	    const dRegistrarCost = (domain.costCents || domain.priceCents) * dTerm.years; // cost (registrar)
478	    if (domain.user.balanceCents < dRenewCents) {
479	      const already = await db.notification.findFirst({
480	        where: {
481	          userId: domain.userId,
482	          title: { contains: domain.name },
483	          AND: { title: { contains: "auto-renew failed" } },
484	          createdAt: { gt: new Date(now.getTime() - 3 * 86400_000) },
485	        },
486	      });
487	      if (!already) {
488	        await db.notification.create({
489	          data: {
490	            userId: domain.userId,
491	            title: `${domain.name} auto-renew failed — top up to renew`,
492	            body: `Renewal is $${(dRenewCents / 100).toFixed(2)} (${dTerm.label}) but your balance is $${(domain.user.balanceCents / 100).toFixed(2)}. Top up and renew manually before ${domain.expiresAt.toISOString().slice(0, 10)}.`,
493	            href: `/dashboard/domains`,
494	          },
495	        });
496	      }
497	      continue;
498	    }
499	
500	    try {
501	      await renewDomain(domain.name, dTerm.years, dRegistrarCost);
502	    } catch (e) {
503	      console.error(`[billing] domain auto-renew failed for ${domain.name}`, e);
504	      await db.notification.create({
505	        data: {
506	          userId: domain.userId,
507	          title: `${domain.name} auto-renew failed — please renew manually`,
508	          body: `We couldn't renew ${domain.name} automatically: ${String((e as any)?.message ?? e).slice(0, 200)}. Renew it manually from your domains page.`,
509	          href: `/dashboard/domains`,
510	        },
511	      });
512	      continue;
513	    }
514	
515	    const newExpiry = new Date(domain.expiresAt.getTime() + dTerm.years * 365 * 86400_000);
516	    // The registrar renewal already succeeded above, so the cost is committed.
517	    // Charge with the guarded debit (the loop's snapshot balance is stale), and
518	    // CAS the expiry so a concurrent manual renew can't be charged twice. If the
519	    // wallet can't cover it we must STILL record the renewal we paid for — flag it
520	    // as uncharged for ops rather than silently eating it or renewing twice later.
521	    try {
522	      await db.$transaction(async (tx) => {
523	        const advanced = await tx.domain.updateMany({
524	          where: { id: domain.id, expiresAt: domain.expiresAt },
525	          data: { expiresAt: newExpiry },
526	        });
527	        if (advanced.count === 0) throw new AlreadyRenewedError();
528	        await debitWallet(tx, domain.userId, dRenewCents);
529	        await tx.walletTransaction.create({
530	          data: {
531	            userId: domain.userId,
532	            amountCents: -dRenewCents,
533	            description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
534	          },
535	        });
536	        // PAID invoice on the successfully-charged path only (the uncharged
537	        // InsufficientBalance branch below deliberately makes no invoice). Inside
538	        // the CAS-guarded tx, so a repeated sweep rolls it back with the debit.
539	        await tx.invoice.create({
540	          data: invoiceCreateData({
541	            userId: domain.userId,
542	            description: `Domain auto-renewal: ${domain.name} (${dTerm.label})`,
543	            status: "PAID",
544	            period: { start: domain.expiresAt, end: newExpiry },
545	            lineItems: [
546	              { description: `Domain renewal — ${domain.name} (${dTerm.label})`, qty: 1, unitCents: dRenewCents, amountCents: dRenewCents },
547	            ],
548	          }),
549	        });
550	        await tx.auditLog.create({
551	          data: { userId: domain.userId, action: "domain.auto_renewed", detail: domain.name },
552	        });
553	      });
554	    } catch (e) {
555	      if (e instanceof AlreadyRenewedError) {
556	        continue; // someone already advanced this period
557	      }
558	      if (e instanceof InsufficientBalanceError) {
559	        await db.domain.update({ where: { id: domain.id }, data: { expiresAt: newExpiry } });
560	        await db.auditLog.create({
561	          data: {
562	            userId: domain.userId,
563	            action: "domain.renew.uncharged",
564	            detail: `${domain.name}: renewed at registrar but wallet could not be charged ${dRenewCents}c — collect manually`,
565	          },
566	        });
567	        console.error(`[billing] UNCHARGED domain renewal for ${domain.name} (insufficient balance)`);
568	        continue;
569	      }
570	      throw e;
571	    }
572	    await db.notification.create({
573	      data: {
574	        userId: domain.userId,
575	        title: `${domain.name} renewed automatically`,
576	        body: `Charged $${(domain.priceCents / 100).toFixed(2)}. New expiry: ${newExpiry.toISOString().slice(0, 10)}.`,
577	        href: `/dashboard/domains`,
578	      },
579	    });
580	    console.log(`[billing] auto-renewed domain ${domain.name} until ${newExpiry.toISOString()}`);
581	  }
582	}
