3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { requireUser } from "./auth";
7	
8	const schema = z.object({
9	  enabled: z.boolean(),
10	  threshold: z.coerce.number().min(0).max(10000),
11	  amount: z.coerce.number().min(0).max(10000),
12	});
