14	/**
15	 * Persist wallet auto-recharge preferences for the current user. Dollar inputs
16	 * are converted to integer cents. When enabled, both a positive threshold and a
17	 * positive top-up amount are required. This only stores preferences — the actual
18	 * off-session Stripe charge is wired by the orchestrator.
19	 */
20	export async function saveAutoRecharge(
21	  prev: any,
22	  formData: FormData
23	): Promise<{ ok?: boolean; error?: string }> {
24	  const user = await requireUser();
25	  const parsed = schema.safeParse({
26	    enabled: formData.get("enabled") === "on",
27	    threshold: formData.get("threshold") || 0,
28	    amount: formData.get("amount") || 0,
29	  });
30	  if (!parsed.success) {
31	    return { error: parsed.error.issues[0]?.message ?? "Invalid auto-recharge settings." };
32	  }
33	  const { enabled, threshold, amount } = parsed.data;
34	
35	  const thresholdCents = Math.round(threshold * 100);
36	  const amountCents = Math.round(amount * 100);
37	
38	  if (enabled) {
39	    if (amountCents < 500) {
40	      return { error: "Recharge amount must be at least $5.00 when auto-recharge is on." };
41	    }
42	    if (thresholdCents < 0) {
43	      return { error: "Threshold can't be negative." };
44	    }
45	  }
46	
47	  await db.user.update({
48	    where: { id: user.id },
49	    data: {
50	      autoRechargeEnabled: enabled,
51	      autoRechargeThresholdCents: enabled ? thresholdCents : null,
52	      autoRechargeAmountCents: enabled ? amountCents : null,
53	    },
54	  });
55	
56	  revalidatePath("/dashboard/billing");
57	  return { ok: true };
58	}
